mapper.sql:
WHERE h.deleted_yn = 'N' AND l.deleted_yn = 'N'
AND h.business_date >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND h.business_date < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND h.due_date >= TO_DATE(#{dueStartDate}, 'YYYY-MM-DD')
AND h.due_date < TO_DATE(#{dueEndDate}, 'YYYY-MM-DD') + 1
AND h.progress_status = #{progressStatus}
AND UPPER(l.specification) LIKE '%' || UPPER(TRIM(#{specification})) || '%'
AND h.warehouse_id IN
#{warehouseId}
AND h.partner_id IN
#{partnerId}
AND l.item_id IN
#{itemId}
AND h.assignee_id IN
#{assigneeId}
AND l.unit_price >=#{minUnitPrice}
AND l.unit_price <=#{maxUnitPrice}
AND ( UPPER(h.sales_order_no) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR TO_CHAR(h.business_date, 'YYYY-MM-DD') LIKE '%' || TRIM(#{keyword}) || '%' OR TO_CHAR(h.business_date, 'YYYY/MM/DD') LIKE '%' || TRIM(#{keyword}) || '%' OR TO_CHAR(h.due_date, 'YYYY-MM-DD') LIKE '%' || TRIM(#{keyword}) || '%' OR TO_CHAR(h.due_date, 'YYYY/MM/DD') LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(i.item_code) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(l.item_name) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(l.specification) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(l.unit) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(h.partner_name) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(h.warehouse_name) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(h.assignee_name) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(h.note) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(l.note) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' )

mapper.select:
SELECT 
FROM SALES_ORDER h
JOIN SALES_ORDER_LINE l ON l.sales_order_id = h.sales_order_id
LEFT JOIN item i ON i.item_id = l.item_id




	AND l.quantity >= #{minQuantity}


	AND l.quantity <= #{maxQuantity}


	AND l.supply_amount >= #{minSupplyAmount}


	AND l.supply_amount <= #{maxSupplyAmount}


	AND l.vat_amount >= #{minVatAmount}


	AND l.vat_amount <= #{maxVatAmount}

ORDER BY h.business_date ASC, h.sales_order_id ASC, l.sales_order_line_id ASC

SELECT remaining_row.* FROM( SELECT supply_row.*, ROUND(supply_row.remaining_supply_amount * 0.1, 0) AS remaining_vat_amount FROM( SELECT quantity_row.*, ROUND(quantity_row.remaining_quantity * quantity_row.unit_price, 0) AS remaining_supply_amount FROM( SELECT , GREATEST(l.quantity - NVL(sold_line.sold_quantity, 0), 0) AS remaining_quantity FROM SALES_ORDER h JOIN SALES_ORDER_LINE l on l.sales_order_id = h.sales_order_id LEFT JOIN ITEM i on i.item_id = l.item_id LEFT JOIN( SELECT sale_line.sales_order_line_id, SUM(sale_line.quantity) AS sold_quantity FROM SALE_LINE sale_line JOIN SALE sale_header ON sale_header.sale_id = sale_line.sale_id WHERE sale_line.deleted_yn = 'N' AND sale_header.deleted_yn = 'N'
AND sale_header.business_date < TO_DATE(#{cutoffDate}, 'YYYY-MM-DD') + 1
GROUP BY sale_line.sales_order_line_id ) sold_line ON sold_line.sales_order_line_id = l.sales_order_line_id
AND h.business_date < TO_DATE(#{cutoffDate}, 'YYYY-MM-DD') + 1
) quantity_row ) supply_row ) remaining_row
WHERE remaining_row.remaining_quantity > 0
AND remaining_row.remaining_quantity >= #{minQuantity}
AND remaining_row.remaining_quantity <= #{maxQuantity}
AND remaining_row.remaining_supply_amount >= #{minSupplyAmount}
AND remaining_row.remaining_supply_amount <= #{maxSupplyAmount}
AND remaining_row.remaining_vat_amount >= #{minVatAmount}
AND remaining_row.remaining_vat_amount <= #{maxVatAmount}
ORDER BY remaining_row.business_date ASC, remaining_row.sales_order_id ASC, remaining_row.sales_order_line_id ASC
